void test_FR_014_01(void)
{
    motion_sample_t sample;
    motion_processor_status_t status;
    const int32_t threshold_millig = (int32_t)APP_MOTION_WIDE_TURN_THRESHOLD_MILLIG;
    const int32_t raw_x_delta =
        (threshold_millig * (int32_t)APP_MOTION_SENSITIVITY_LSB_PER_G + 999) / 1000;

    /* Record a level, then finish calibration with the same level. */
    status = motion_processor_process(0, 0, 8192, 0U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_CALIBRATING, status);

    status = motion_processor_process(0, 0, 8192,
                                      APP_MOTION_CALIBRATION_DURATION_MS, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_TRUE(sample.is_calibrated);

    /* The first calibrated sample establishes the event window baseline. */
    status = motion_processor_process(0, 0, 8192,
                                      APP_MOTION_CALIBRATION_DURATION_MS + 1U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_TRUE(sample.is_calibrated);

    /* A threshold-sized positive X change within the event window is a wide turn. */
    status = motion_processor_process((int16_t)raw_x_delta, 0, 8192,
                                      APP_MOTION_CALIBRATION_DURATION_MS + 2U, &sample);
    TEST_ASSERT_EQUAL_INT(MOTION_PROCESSOR_STATUS_OK, status);
    TEST_ASSERT_EQUAL_INT(MOTION_EVENT_WIDE_TURN, sample.event);
    TEST_ASSERT_EQUAL_STRING("Wide Turn", motion_processor_event_name(sample.event));
}
